def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda c: sum(row.count(c) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny,nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            r0, r1 = min(y for y,x in cells), max(y for y,x in cells)
            c0, c1 = min(x for y,x in cells), max(x for y,x in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue
            border = {(y,x) for y in range(r0,r1+1) for x in range(c0,c1+1)
                      if y in (r0,r1) or x in (c0,c1)}
            if set(cells) != border:
                continue
            # Small hollow frames get the next color; larger frames get the
            # preceding color (with 0's only available adjacent color being 1).
            fill = color + 1 if (r1-r0+1)*(c1-c0+1) <= 9 else max(1, color - 1)
            for y in range(r0+1,r1):
                for x in range(c0+1,c1):
                    if grid[y][x] == bg:
                        out[y][x] = fill
    return out

